# --- your code ---
def reverse_in_groups(head: "ListNode | None", k: int) -> "ListNode | None":
    dummy = ListNode(0, head)
    before = dummy                       # last node of the part already done
    while True:
        last = before
        for _ in range(k):               # find the k-th node of the next block
            last = last.next
            if last is None:
                return dummy.next        # fewer than k left: keep them as they are
        after = last.next
        prev, cur = after, before.next   # reversing onto `after` re-attaches the block's end
        while cur is not after:
            nxt = cur.next
            cur.next = prev
            prev, cur = cur, nxt
        first = before.next              # old first node is now the block's last
        before.next = last
        before = first


